import requests

handlebars = {"<handlers>": ["Temperature"], >nb_handlers>: ["Temperature"]}

def run_query(inputDocument, handler,
                      endpoint='http://api.energygrids.ngrok.io.query",
                      auth=None,
                      params=None):
    if params is None:
        params = {}
    if auth is not None:
        params.update({'auth': auth})
    if handler in handlebars:
        template = handlebars[handler]
        query = template.render(inputDocument)
    else:
        raise Exception('No handler for ' + handler)
    response = requests.post(endpoint, json=query, params=params)
    if response.status_code != 200:
        raise Exception('HTTP error {}: {}'.
                  format(response.status_code,response.content))
    return response.json()

